<?php
require_once __DIR__ . '/config/database.php';require_once __DIR__ . '/includes/functions.php';require_login();
$stmt=$pdo->prepare("SELECT b.*,w.nama AS wisata_nama,p.status AS pembayaran_status,p.bukti,p.catatan FROM bookings b JOIN wisata w ON w.id=b.wisata_id LEFT JOIN pembayaran p ON p.booking_id=b.id WHERE b.user_id=? ORDER BY b.created_at DESC");$stmt->execute([$_SESSION['user']['id']]);$rows=$stmt->fetchAll();
$pageTitle='Riwayat booking';require __DIR__.'/includes/header.php';
?>
<section class="container page-top"><span class="eyebrow" style="color:var(--green)">AKUN KAMU</span><h1>Riwayat booking</h1><p>Periksa status pemesanan dan pembayaran tiket wisata.</p></section><section class="container section section-tight">
<?php if(!$rows): ?><div class="empty">Kamu belum punya pemesanan. <a href="wisata.php">Cari wisata sekarang</a>.</div><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Kode / Wisata</th><th>Tanggal</th><th>Tiket</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= e($r['kode_booking']) ?></strong><br><?= e($r['wisata_nama']) ?></td><td><?= e($r['tanggal']) ?></td><td><?= (int)$r['jumlah'] ?></td><td><?= rupiah($r['total']) ?></td><td><span class="status <?= e($r['status']) ?>"><?= e(ucfirst($r['status'])) ?></span><?php if($r['pembayaran_status']==='ditolak' && $r['catatan']): ?><br><small><?= e($r['catatan']) ?></small><?php endif; ?></td><td><?php if(!in_array($r['status'],['terverifikasi','dibatalkan'],true)): ?><a class="btn small" href="pembayaran.php?id=<?= (int)$r['id'] ?>">Pembayaran</a><?php else: ?><span class="muted">—</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php require __DIR__.'/includes/footer.php'; ?>
